const $=id=>document.getElementById(id);
const selectedPdfLayouts={invoice:null,quotation:null};
const PDF_BRAND_LAYOUTS={
  prime:"data:image/jpeg;base64,",
  kannur:"data:image/jpeg;base64,"
};
const key={products:"iq_products",settings:"iq_settings",files:"iq_files",counts:"iq_counts"};
const PDF_HEADER="data:image/jpeg;base64,";
const AUTH_SIGNATURE="data:image/png;base64,";
const today=()=>new Date().toISOString().slice(0,10);
let products=[];
let settings=JSON.parse(localStorage.getItem(key.settings)||"{}");
let files=[];
let legacyFiles=[];
try{legacyFiles=JSON.parse(localStorage.getItem(key.files)||"[]")}catch(_){legacyFiles=[]}
let counts=JSON.parse(localStorage.getItem(key.counts)||'{"invoice":0,"quotation":0}');
let lines={invoice:[],quotation:[]};
let editingFileId=null;
let editingProductId=null;

let productDBPromise;
function openProductDB(){
 if(productDBPromise)return productDBPromise;
 productDBPromise=new Promise((resolve,reject)=>{
  if(!window.indexedDB)return reject(new Error("IndexedDB is not supported by this browser."));
  const req=indexedDB.open("QuotationMakerStorage",2);
  req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains("products"))db.createObjectStore("products",{keyPath:"id"});if(!db.objectStoreNames.contains("files"))db.createObjectStore("files",{keyPath:"id"});};
  req.onsuccess=()=>resolve(req.result);
  req.onerror=()=>reject(req.error||new Error("Could not open browser database."));
  req.onblocked=()=>reject(new Error("Browser database is blocked by another open tab. Close other copies of this website and try again."));
 });
 productDBPromise=productDBPromise.catch(err=>{productDBPromise=null;throw err;});
 return productDBPromise;
}
async function readProductRecordsFromDB(){
 const db=await openProductDB();
 return await new Promise((resolve,reject)=>{
  const tx=db.transaction("products","readonly"),req=tx.objectStore("products").getAll();
  req.onsuccess=()=>resolve(Array.isArray(req.result)?req.result:[]);
  req.onerror=()=>reject(req.error||new Error("Could not read products."));
 });
}
async function loadProductsDB(){
 let local=[];
 try{local=JSON.parse(localStorage.getItem(key.products)||"[]");if(!Array.isArray(local))local=[];}catch(_){local=[];}
 let stored=[];
 try{stored=await readProductRecordsFromDB();}catch(err){console.warn("Could not read IndexedDB products; using local backup.",err);return local;}
 // Merge by ID instead of letting an old localStorage snapshot hide newer IndexedDB records.
 // IndexedDB values win for matching IDs; records found in only one store are retained.
 const merged=new Map();
 local.forEach(item=>{if(item&&item.id!=null)merged.set(String(item.id),item);});
 stored.forEach(item=>{if(item&&item.id!=null)merged.set(String(item.id),item);});
 const chosen=[...merged.values()];
 // Repair the IndexedDB copy from the merged result. A localStorage quota error is harmless.
 try{await new Promise((resolve,reject)=>{const dbReq=productDBPromise;dbReq.then(db=>{const tx=db.transaction("products","readwrite"),store=tx.objectStore("products");store.clear();chosen.forEach(item=>store.put(item));tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);}).catch(reject);});}catch(err){console.warn("Could not reconcile product database.",err);}
 try{localStorage.setItem(key.products,JSON.stringify(chosen));}catch(_){/* IndexedDB remains the primary persistent store. */}
 return chosen;
}
async function saveProductsDB(list){
 const safeList=Array.isArray(list)?list:[];
 // IndexedDB is the primary store because product images can exceed localStorage quota.
 let dbSaved=false,dbError=null;
 try{
  const db=await openProductDB();
  await new Promise((resolve,reject)=>{
   const tx=db.transaction("products","readwrite"),store=tx.objectStore("products");
   store.clear();safeList.forEach(item=>store.put(item));
   tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error||new Error("Browser database could not save product data."));tx.onabort=()=>reject(tx.error||new Error("Saving products was cancelled."));
  });
  dbSaved=true;
 }catch(err){dbError=err;}
 let localSaved=false;
 try{localStorage.setItem(key.products,JSON.stringify(safeList));localSaved=true;}catch(err){console.warn("Product local backup could not be written; product images or browser quota may be too large.",err);}
 if(!dbSaved&&!localSaved)throw dbError||new Error("Could not save products to browser storage.");
 if(!dbSaved)console.warn("IndexedDB save failed; product data saved only in localStorage.",dbError);
}
async function loadFilesDB(){
  let local=[];try{local=JSON.parse(localStorage.getItem(key.files)||"[]");if(!Array.isArray(local))local=[];}catch(_){local=[];}
  try{
    const db=await openProductDB();
    const stored=await new Promise((resolve,reject)=>{const tx=db.transaction("files","readonly"),req=tx.objectStore("files").getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error||new Error("Could not read saved documents."));});
    // Merge local fields (newest status/details) onto IndexedDB records, preserving the full preview HTML when available.
    const map=new Map(stored.map(item=>[String(item.id),item]));
    local.forEach(item=>map.set(String(item.id),{...(map.get(String(item.id))||{}),...item,html:item.html||(map.get(String(item.id))||{}).html}));
    const chosen=[...map.values()];
    if(chosen.length){try{await new Promise((resolve,reject)=>{const tx=db.transaction("files","readwrite"),store=tx.objectStore("files");store.clear();chosen.forEach(item=>store.put(item));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}catch(_){}}
    return chosen;
  }catch(err){console.warn("Using local saved-document backup.",err);return local;}
}
async function saveFilesDB(list){
  let localSaved=false;
  try{const compact=list.map(item=>{const copy={...item};delete copy.html;return copy;});localStorage.setItem(key.files,JSON.stringify(compact));localSaved=true;}catch(err){console.warn("Could not write saved-document recovery copy.",err);}
  try{
    const db=await openProductDB();
    await new Promise((resolve,reject)=>{const tx=db.transaction("files","readwrite"),store=tx.objectStore("files");store.clear();list.forEach(item=>store.put(item));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error("Saved documents could not be stored."));tx.onabort=()=>reject(tx.error||new Error("Saving documents was cancelled."));});
  }catch(err){if(!localSaved)throw err;console.warn("IndexedDB saved-document save failed; localStorage copy retained.",err);}
}
function exportLocalBackup(){
  const payload={format:"quotation-maker-backup",version:1,exportedAt:new Date().toISOString(),products,files,settings,counts};
  const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"});
  const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="Quotation-Maker-Backup-"+new Date().toISOString().slice(0,10)+".json";document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
async function importLocalBackup(input){
  const file=input.files&&input.files[0];if(!file)return;
  try{
    const data=JSON.parse(await file.text());
    if(data.format!=="quotation-maker-backup"||!Array.isArray(data.products)||!Array.isArray(data.files))throw new Error("This is not a valid Quotation Maker backup file.");
    if(!confirm("Import this backup? Records with matching IDs will be updated; other records will be kept."))return;
    const merge=(current,incoming)=>{const map=new Map(current.map(x=>[String(x.id),x]));incoming.forEach(x=>map.set(String(x.id),{...(map.get(String(x.id))||{}),...x}));return [...map.values()];};
    products=merge(products,data.products);files=merge(files,data.files).map(normalizeFileStatus);
    if(data.settings&&typeof data.settings==="object")settings={...settings,...data.settings};
    if(data.counts&&typeof data.counts==="object")counts={...counts,...data.counts};
    localStorage.setItem(key.settings,JSON.stringify(settings));localStorage.setItem(key.counts,JSON.stringify(counts));
    await Promise.all([saveProductsDB(products),saveFilesDB(files)]);
    renderProducts();updateProducts("invoice");updateProducts("quotation");renderFiles("all");updateDashboard();alert("Backup imported successfully.");
  }catch(err){alert("Could not import backup: "+(err.message||String(err)));}
  finally{input.value="";}
}
async function save(){localStorage.setItem(key.settings,JSON.stringify(settings));localStorage.setItem(key.counts,JSON.stringify(counts));await Promise.all([saveProductsDB(products),saveFilesDB(files)]);}
function number(type){counts[type]=(counts[type]||0)+1;save();return (type==="invoice"?"INV-":"QUO-")+String(counts[type]).padStart(4,"0")}
function setupDoc(type){
  const prefix=type==="invoice"?"Proforma Invoice":"Quotation";
  editingFileId=null;
  $(type+"No").value=number(type);$(type+"Date").value=today();lines[type]=[];
  ["Customer","Phone","Address","Sales"].forEach(x=>$(type+x).value="");
  updateProducts(type);$(type+"Price").value="";renderLines(type);
  const btn=$(type+"SaveButton"); if(btn)btn.textContent="Save PDF";
}
function updateProducts(type){
  const sel=$(type+"Product"); const search=$(type+"Search").value.toLowerCase();
  sel.innerHTML='<option value="">Choose product</option>'+products.filter(p=>(p.name+" "+p.code).toLowerCase().includes(search)).map(p=>`<option value="${p.id}">${esc(p.name)} (${esc(p.code)}) - ₹${money(p.price)}</option>`).join("");
}
function syncSelectedPrice(type){
 const p=products.find(x=>x.id===$(type+"Product").value); const input=$(type+"Price"); if(input) input.value=p?Number(p.price||0):"";
}
function addLine(type){
  const p=products.find(x=>x.id===$(type+"Product").value); if(!p)return alert("Please choose a product.");
  const existing=lines[type].filter(l=>l.id===p.id).reduce((sum,l)=>sum+(Number(l.qty)||1),0);
  const stock=Number(p.qty);
  if(!Number.isInteger(stock)||stock<0) return alert(`Stock quantity for ${p.name} is invalid. Please edit the product and correct its stock.`);
  if(existing+1>stock) return alert(`Insufficient stock for ${p.name}. Available: ${stock}; already added to this ${type}: ${existing}.`);
  const rawPrice=$(type+"Price").value;
  const entered=rawPrice===""?Number(p.price):Number(rawPrice);
  if(!Number.isFinite(entered)||entered<0) return alert("Price must be a valid number greater than or equal to zero.");
  lines[type].push({id:p.id,qty:1,price:entered}); renderLines(type); $(type+"Product").value=""; $(type+"Price").value="";
}
function renderLines(type){
 const wrap=$(type+"Lines");
 if(!lines[type].length){wrap.innerHTML='<div class="empty">No products added.</div>';renderTotals(type);return}
 const rows=lines[type].map((l,i)=>{const p=products.find(x=>x.id===l.id); if(!p)return '';
   const price=Number(l.price??p.price)||0, qty=Number(l.qty)||1, amount=price*qty, tax=amount*(Number(p.gst)||0)/100;
   return `<tr><td>${p.image?`<img class="line-product-image" src="${p.image}" alt="">`:''}<span>${esc(p.name)}<small>${esc(p.code)}</small></span></td><td><input class="price-edit" type="number" min="0" step="0.01" value="${price}" onchange="changePrice('${type}',${i},this.value)" title="Edit price / discount price"></td>${type==="invoice"?`<td><input class="qty" type="number" min="1" value="${qty}" onchange="changeQty('${type}',${i},this.value)"></td>`:""}<td>${p.gst}%</td><td>₹${money(amount)}</td><td>₹${money(tax)}</td><td>₹${money(amount+tax)}</td><td><button class="danger" onclick="removeLine('${type}',${i})">Delete</button></td></tr>`;
 }).join("");
 wrap.innerHTML=`<table class="line-table"><thead><tr><th>Product</th><th>Price</th>${type==="invoice"?"<th>Qty</th>":""}<th>GST</th><th>Amount</th><th>Tax</th><th>Total</th><th></th></tr></thead><tbody>${rows}</tbody></table>`;renderTotals(type)
}
function changeQty(type,i,v){
 const line=lines[type][i], p=products.find(x=>x.id===line.id); if(!p)return;
 const requested=Number(v), max=Math.max(0,Number(p.qty)||0);
 if(!Number.isInteger(requested)||requested<1){alert("Quantity must be at least 1.");renderLines(type);return}
 const otherQty=lines[type].reduce((sum,l,index)=>sum+(index!==i&&l.id===line.id?(Number(l.qty)||1):0),0);
 if(requested+otherQty>max){alert(`Quantity cannot exceed available stock. Available: ${max}; already allocated on this document: ${otherQty}.`);renderLines(type);return}
 line.qty=requested;renderLines(type)
}
function changePrice(type,i,v){
 const n=Number(v);
 if(String(v).trim()===""||!Number.isFinite(n)||n<0){alert("Price must be a valid number greater than or equal to zero.");renderLines(type);return}
 lines[type][i].price=n;renderLines(type)
}
function removeLine(type,i){lines[type].splice(i,1);renderLines(type)}
function totals(type){let subtotal=0,tax=0;lines[type].forEach(l=>{let p=products.find(x=>x.id===l.id);if(!p)return;let a=(Number(l.price??p.price)||0)*(Number(l.qty)||1);subtotal+=a;tax+=a*(Number(p.gst)||0)/100});return {subtotal,tax,total:subtotal+tax}}
function renderTotals(type){let t=totals(type);$(type+"Totals").innerHTML=`<div class="total-row"><span>Subtotal</span><b>₹${money(t.subtotal)}</b></div><div class="total-row"><span>GST</span><b>₹${money(t.tax)}</b></div><div class="total-row grand"><span>Grand Total</span><b>₹${money(t.total)}</b></div>`}
function clearProductForm(){
 ["pName","pCode","pPrice","pQty"].forEach(id=>$(id).value="");
 $("pGst").value="18";$("pImage").value="";
 editingProductId=null;
 $("productSaveButton").textContent="Add Product";
 $("productCancelButton").style.display="none";
 $("productFormStatus").textContent="";
}
function editProduct(id){
 const p=products.find(x=>x.id===id); if(!p)return;
 editingProductId=id;
 $("pName").value=p.name||"";$("pCode").value=p.code||"";$("pPrice").value=p.price??"";
 $("pQty").value=p.qty??0;$("pGst").value=p.gst??18;$("pImage").value="";
 $("productSaveButton").textContent="Update Product";
 $("productCancelButton").style.display="inline-block";
 $("productFormStatus").textContent="Editing "+p.name+". Leave image empty to keep the existing image.";
 $("pName").focus();
}
function cancelProductEdit(){clearProductForm();}
function addProduct(){
 const name=$("pName").value.trim(),code=$("pCode").value.trim(),priceRaw=$("pPrice").value,qtyRaw=$("pQty").value,gstRaw=$("pGst").value;
 const price=Number(priceRaw),qty=Number(qtyRaw),gst=Number(gstRaw);
 if(!name||!code)return alert("Product name and product code are required.");
 if(name.length>120)return alert("Product name must be 120 characters or fewer.");
 if(code.length>60)return alert("Product code must be 60 characters or fewer.");
 if(priceRaw===""||!Number.isFinite(price)||price<0||!/^\d+(\.\d{1,2})?$/.test(priceRaw.trim()))return alert("Enter a valid price with no more than 2 decimal places.");
 if(qtyRaw===""||!Number.isInteger(qty)||qty<0||qty>1000000000)return alert("Enter a whole-number stock quantity between 0 and 1,000,000,000.");
 if(gstRaw===""||!Number.isFinite(gst)||gst<0||gst>100||!/^\d+(\.\d{1,2})?$/.test(gstRaw.trim()))return alert("Enter a valid GST percentage between 0 and 100, with up to 2 decimal places.");
 if(products.some(p=>String(p.code).toLowerCase()===code.toLowerCase() && p.id!==editingProductId))return alert("A product with this code already exists. Please use a unique code.");
 const file=$("pImage").files[0];
 if(file && !file.type.startsWith("image/"))return alert("Please select a valid image file.");
 if(file && file.size>2*1024*1024)return alert("Product image must be 2 MB or smaller. Choose a smaller image to prevent browser storage errors.");
 const currentEditId=editingProductId;
 const finish=async (image)=>{
   try {
     if(currentEditId){
       const item=products.find(p=>p.id===currentEditId);
       if(!item)return alert("The product being edited no longer exists.");
       item.name=name;item.code=code;item.price=price;item.qty=qty;item.gst=gst;
       if(image) item.image=image;
       await saveProductsDB(products);
     }else{
       const item={id:(Date.now().toString()+Math.random().toString(36).slice(2,7)),name,code,price,qty,gst,image:image||""};
       products.push(item);await saveProductsDB(products);
     }
     clearProductForm();
     renderProducts();updateProducts("invoice");updateProducts("quotation");updateDashboard();
     $("productFormStatus").textContent=currentEditId?"Product updated and saved for future use.":"Product added and saved for future use.";
   } catch(err) {
     if(!currentEditId) products=products.filter(p=>!(p.name===name&&p.code===code));
     alert("Could not save this product to browser database. Check available device storage or browser permissions. Details: "+(err&&err.message?err.message:"Unknown error"));
   }
 };
 if(file){
   const r=new FileReader();r.onload=()=>finish(r.result);r.onerror=()=>alert("Could not read the selected image. Please try again.");r.readAsDataURL(file);
 }else finish("");
}
function renderProducts(){
 const q=($("productSearch")?.value||"").toLowerCase();
 const arr=products.filter(p=>(p.name+" "+p.code).toLowerCase().includes(q));
 $("productList").innerHTML=arr.length?arr.map(p=>`<div class="product-row"><div class="product-list-name">${p.image?`<img src="${p.image}" alt="">`:''}<b>${esc(p.name)}</b></div><span>${esc(p.code)}</span><span>₹${money(p.price)}</span><span>Qty: ${p.qty}</span><span>GST: ${p.gst}%</span><div class="product-actions"><button class="secondary" onclick="editProduct('${p.id}')">Edit</button><button class="danger" onclick="deleteProduct('${p.id}')">Delete</button></div></div>`).join(""):'<div class="empty">No products added.</div>';
}
async function deleteProduct(id){
 if(confirm("Delete this product?")){
   products=products.filter(p=>p.id!==id);
   await saveProductsDB(products);
   if(editingProductId===id)clearProductForm();
   renderProducts();updateProducts("invoice");updateProducts("quotation");updateDashboard();
 }
}

function saveSettings(){
 const name=$("sName").value.trim(), phone=$("sPhone").value.trim(), email=$("sEmail").value.trim(), gst=$("sGst").value.trim(), website=$("sWebsite").value.trim();
 if(name.length>150)return alert("Company name must be 150 characters or fewer.");
 if(phone && !isValidPhone(phone))return alert("Enter a valid Indian mobile number: 10 digits starting with 6–9. You may also use +91, 91, or a leading 0.");
 if(email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return alert("Enter a valid company email address.");
 if(gst && !/^[A-Za-z0-9]{5,20}$/.test(gst))return alert("GSTIN should contain 5–20 letters or numbers.");
 if(website && !/^(https?:\/\/)?([\w-]+\.)+[\w-]{2,}(\/.*)?$/i.test(website))return alert("Enter a valid website address, such as www.example.com.");
 settings={name,address:$("sAddress").value.trim(),phone,email,gst,website,bank:$("sBank").value.trim(),accountName:$("sAccountName").value.trim(),accountNo:$("sAccountNo").value.trim(),ifsc:$("sIfsc").value.trim(),branch:$("sBranch").value.trim(),upi:$("sUpi").value.trim(),terms:$("sTerms").value};
 if(settings.ifsc && !/^[A-Za-z]{4}0[A-Za-z0-9]{6}$/.test(settings.ifsc))return alert("Enter a valid IFSC code (example: ABCD0123456).");
 if(settings.upi && !/^[\w.-]{2,}@[\w.-]{2,}$/.test(settings.upi))return alert("Enter a valid UPI ID.");
 if(settings.accountNo && !/^\d{6,30}$/.test(settings.accountNo.replace(/\s/g,"")))return alert("Bank account number should contain 6–30 digits.");
 try{save();$("settingsStatus").textContent="Settings saved.";setTimeout(()=>$ ("settingsStatus").textContent="",2000)}catch(e){alert("Could not save settings. Browser storage may be full.")}
}
function loadSettings(){let s=settings;Object.entries({sName:"name",sAddress:"address",sPhone:"phone",sEmail:"email",sGst:"gst",sWebsite:"website",sBank:"bank",sAccountName:"accountName",sAccountNo:"accountNo",sIfsc:"ifsc",sBranch:"branch",sUpi:"upi",sTerms:"terms"}).forEach(([id,k])=>$(id).value=s[k]||"")}
function makePDFHTML(type){
 const t=totals(type), s=settings, no=$(type+"No").value, date=$(type+"Date").value, isInvoice=type==="invoice";
 const rows=lines[type].map((l,i)=>{const p=products.find(x=>x.id===l.id);if(!p)return '';const price=Number(l.price??p.price)||0,qty=isInvoice?(Number(l.qty)||1):1,amount=price*qty,tax=amount*(Number(p.gst)||0)/100;
   return `<tr><td class="num slno">${i+1}</td><td class="image-cell">${p.image?`<img class="pdf-product-image" src="${p.image}" alt="">`:'—'}</td><td><strong>${esc(p.name)}</strong><small>${esc(p.code)}</small></td><td class="num">₹${money(price)}</td><td class="num">${qty}</td><td class="num">${p.gst}%</td><td class="num">₹${money(amount)}</td><td class="num">₹${money(tax)}</td><td class="num">₹${money(amount+tax)}</td></tr>`}).join('');
 return `<div class="pdf-sheet"><div class="pdf-fixed-header"><img src="${PDF_HEADER}" alt="Company Header"></div><div class="pdf-content">
  <div class="pdf-doc-meta"><div class="pdf-doc-type">${isInvoice?"PROFORMA INVOICE":"QUOTATION"}</div><div><span>${isInvoice?"PI No":"Quotation No"}</span><b>${esc(no)}</b></div><div><span>Date</span><b>${esc(date)}</b></div></div>
   <div class="pdf-customer-block"><div class="pdf-section-title">To</div><div class="customer-grid"><div><span>Customer Name</span><b>${esc($(type+"Customer").value||"—")}</b></div><div><span>Phone Number</span><b>${esc($(type+"Phone").value||"—")}</b></div><div><span>Address</span><b>${nl($(type+"Address").value||"—")}</b></div><div><span>Salesperson Name</span><b>${esc($(type+"Sales").value||"—")}</b></div></div></div>
   <table class="pdf-items"><thead><tr><th class="num slno">SL No.</th><th class="image-cell">Image</th><th>Product</th><th class="num">Price</th><th class="num">Qty</th><th class="num">GST</th><th class="num">Amount</th><th class="num">Tax</th><th class="num">Total</th></tr></thead><tbody>${rows}</tbody></table>
   ${isInvoice?`<div class="pdf-summary"><div><span>Subtotal</span><b>₹${money(t.subtotal)}</b></div><div><span>GST / Tax</span><b>₹${money(t.tax)}</b></div><div class="pdf-grand"><span>Grand Total</span><b>₹${money(t.total)}</b></div></div>`:""}
   <div class="pdf-info-grid"><div class="pdf-info-box"><h3>Bank Details</h3><div><span>Bank</span><b>${esc(s.bank||"—")}</b></div><div><span>Account Name</span><b>${esc(s.accountName||"—")}</b></div><div><span>Account No.</span><b>${esc(s.accountNo||"—")}</b></div><div><span>IFSC</span><b>${esc(s.ifsc||"—")}</b></div><div><span>Branch</span><b>${esc(s.branch||"—")}</b></div><div><span>UPI</span><b>${esc(s.upi||"—")}</b></div></div><div class="pdf-info-box"><h3>Terms &amp; Conditions</h3>${(s.terms||"1. Payment Terms: Immediate Payment\n2. Price: Indicates the cost of each item.\n3. Taxes: As shown above.\n4. Shipping Cost: Extra").split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map((x,i)=>`<div class="pdf-term-line"><span class="pdf-term-number">${i+1}.</span><span class="pdf-term-text">${esc(x.replace(/^\d+\.\s*/,""))}</span></div>`).join("")}</div></div>
   <div class="pdf-signature-section"><img src="${AUTH_SIGNATURE}" alt="Authorised Signature"><div class="pdf-signature-label">Authorised Signature</div></div><div class="pdf-address-bottom"><div class="pdf-company-name">${esc(s.name||"")}</div><div>${s.phone?`Phone: ${esc(s.phone)}`:""}${s.email?` &nbsp; | &nbsp; Email: ${esc(s.email)}`:""}</div><div>${s.gst?`GSTIN: ${esc(s.gst)}`:""}${s.website?` &nbsp; | &nbsp; ${esc(s.website)}`:""}</div><div>${esc(s.address||"")}</div></div>
 </div><div class="pdf-fixed-footer"><span>${esc(s.name||"")}</span></div></div>`;
}
function setPDFStatus(type,message,isError=true){
 const section=$(type); if(!section)return;
 let status=$(type+'PdfStatus');
 if(!status){status=document.createElement('div');status.id=type+'PdfStatus';status.setAttribute('role','status');status.style.cssText='margin:10px 0;padding:9px 12px;border-radius:6px;font-weight:700;font-size:13px;';const actions=section.querySelector('.actions');if(actions) section.insertBefore(status,actions);else section.appendChild(status);}
 status.textContent=message||'';status.style.display=message?'block':'none';status.style.color=isError?'#b42318':'#067647';status.style.background=isError?'#fef3f2':'#ecfdf3';
}
function handlePdfLayoutChange(type){
 const layout=$(type+"PdfLayout")?.value||"jimco";
 const help=$(type+"PdfLayout")?.closest(".pdf-layout-choice")?.querySelector(".layout-help");
 if(help)help.textContent=selectedPdfLayouts[type]?"Your uploaded letterhead will be used for the PDF.":layout==="jimco"?"The standard JIMCO EXIM PDF layout will be used.":layout==="prime"?"PRIME SOLUTIONS letterhead will be used for the PDF.":"KANNUR SAFETY letterhead will be used for the PDF."
}
function loadPdfLayoutImage(type,input){
 const file=input?.files?.[0];if(!file)return;
 if(!file.type.startsWith("image/")){setPDFStatus(type,"Please choose an image file for the PDF layout.",true);input.value="";return;}
 if(file.size>8*1024*1024){setPDFStatus(type,"Please choose an image smaller than 8 MB.",true);input.value="";return;}
 const reader=new FileReader();reader.onload=()=>{
   const img=new Image();img.onload=()=>{
     const canvas=document.createElement("canvas");canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;
     const ctx=canvas.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0);
     selectedPdfLayouts[type]=canvas.toDataURL("image/jpeg",0.92);
     const preview=$(type+"PdfLayoutPreview");if(preview){preview.innerHTML="";const thumb=document.createElement("img");thumb.src=selectedPdfLayouts[type];thumb.alt="Selected PDF layout";preview.appendChild(thumb);preview.style.display="block";}
     const removeButton=$(type+"RemovePdfLayout");if(removeButton)removeButton.style.display="inline-flex";
     const help=$(type+"PdfLayout")?.closest(".pdf-layout-choice")?.querySelector(".layout-help");if(help)help.textContent="Your uploaded layout will be used instead of the preset for this PDF.";
     setPDFStatus(type,"Custom PDF layout selected.",false);
   };img.onerror=()=>setPDFStatus(type,"Could not read that image. Please choose another one.",true);img.src=reader.result;
 };reader.onerror=()=>setPDFStatus(type,"Could not load the selected image.",true);reader.readAsDataURL(file);
}
function removePdfLayoutImage(type){
 selectedPdfLayouts[type]=null;
 const input=$(type+"PdfLayoutUpload");if(input)input.value="";
 const preview=$(type+"PdfLayoutPreview");if(preview){preview.innerHTML="";preview.style.display="none";}
 const removeButton=$(type+"RemovePdfLayout");if(removeButton)removeButton.style.display="none";
 handlePdfLayoutChange(type);
 setPDFStatus(type,"Uploaded layout removed. The selected preset layout will be used.",false);
}
async function savePDF(type){
 setPDFStatus(type,'');
 const fail=message=>{setPDFStatus(type,message,true);return;};
 const customer=$(type+"Customer").value.trim(), phone=$(type+"Phone").value.trim(), date=$(type+"Date").value;
 if(!customer)return fail("Customer name is required before generating a PDF.");
 if(customer.length>150)return fail("Customer name must be 150 characters or fewer.");
 if(phone && !isValidPhone(phone))return fail("Enter a valid Indian mobile number: 10 digits starting with 6–9. You may also use +91, 91, or a leading 0.");
 if(!date || !/^\d{4}-\d{2}-\d{2}$/.test(date) || Number.isNaN(new Date(date+"T00:00:00").getTime()))return fail("Select a valid document date.");
 if(!lines[type].length)return fail("Add at least one product before generating the PDF.");
 const selectedBrand=$(type+"PdfLayout")?.value||"jimco";
 const uploadedLayout=selectedPdfLayouts[type];
 const useCustomLayout=!!uploadedLayout||selectedBrand!=="jimco";
 const selectedLayoutImage=uploadedLayout||PDF_BRAND_LAYOUTS[selectedBrand]||null;
 if(useCustomLayout&&!selectedLayoutImage)return fail("The selected company layout could not be loaded.");
 const customHeaderH=useCustomLayout?48:27;
 const customFooterH=useCustomLayout?36:30;
 for(const l of lines[type]){const p=products.find(x=>x.id===l.id);if(!p)return fail("A selected product no longer exists. Remove it and add the product again.");if(!Number.isFinite(Number(l.price))||Number(l.price)<0)return fail("Every product must have a valid price.");if(type==="invoice"&&(!Number.isInteger(Number(l.qty))||Number(l.qty)<1))return fail("Invoice quantities must be whole numbers greater than zero.");}
 const area=$("pdfArea");area.innerHTML=makePDFHTML(type);const sheet=area.querySelector('.pdf-sheet'),content=area.querySelector('.pdf-content');
 if(useCustomLayout){sheet.classList.add('custom-pdf-layout');sheet.style.backgroundImage=`url("${selectedLayoutImage}")`;sheet.style.backgroundSize='100% 100%';sheet.style.backgroundRepeat='no-repeat';const header=sheet.querySelector('.pdf-fixed-header'),footer=sheet.querySelector('.pdf-fixed-footer');if(header)header.style.display='none';if(footer)footer.style.display='none';content.style.background='transparent';}
 const old={position:area.style.position,left:area.style.left,top:area.style.top,zIndex:area.style.zIndex,visibility:area.style.visibility,display:area.style.display,width:area.style.width};
 Object.assign(area.style,{position:'absolute',left:'0',top:'0',zIndex:'999999',visibility:'visible',display:'block',width:'794px'});
 try{
   if(!window.html2canvas||!window.jspdf?.jsPDF)throw new Error('PDF libraries not loaded');
   const imgs=[...sheet.querySelectorAll('img')];await Promise.all(imgs.map(img=>new Promise(r=>{if(img.complete&&img.naturalWidth)return r();const done=()=>{img.onload=null;img.onerror=null;r()};img.onload=done;img.onerror=done;setTimeout(done,8000)})));if(document.fonts?.ready)await document.fonts.ready;
   await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
   // For a gallery template, render only the document content with transparent
   // backgrounds so it can be composited over the selected image in the PDF.
   // html2canvas can otherwise retain opaque white backgrounds from nested cells.
   const transparentStyleSnapshots=[];
   if(useCustomLayout){
     [content,...content.querySelectorAll('*')].forEach(el=>{
       transparentStyleSnapshots.push({el,bg:el.style.getPropertyValue('background-color'),bgPriority:el.style.getPropertyPriority('background-color'),image:el.style.getPropertyValue('background-image'),imagePriority:el.style.getPropertyPriority('background-image')});
       el.style.setProperty('background-color','transparent','important');
       el.style.setProperty('background-image','none','important');
     });
   }
   let canvas;
   try {
     canvas=await html2canvas(content,{scale:2,backgroundColor:useCustomLayout?null:'#fff',useCORS:true,allowTaint:false,logging:false,width:750,windowWidth:750,scrollX:0,scrollY:0});
   } finally {
     transparentStyleSnapshots.forEach(({el,bg,bgPriority,image,imagePriority})=>{
       if(bg)el.style.setProperty('background-color',bg,bgPriority);else el.style.removeProperty('background-color');
       if(image)el.style.setProperty('background-image',image,imagePriority);else el.style.removeProperty('background-image');
     });
   }
   const pdf=new jspdf.jsPDF({orientation:'portrait',unit:'mm',format:'a4',compress:true});
   const pageW=210,pageH=297,headerH=useCustomLayout?customHeaderH:27,side=6,contentW=198;
   pdf.setFont('helvetica','bold'); pdf.setFontSize(7.2);
   const companyName=String(settings.name||'').trim();
   const phoneEmail=`Phone ${String(settings.phone||'').trim()}${settings.email ? ' | '+String(settings.email).trim() : ''}`;
   const gstWebsite=`GSTIN ${String(settings.gst||'').trim()}${settings.website ? ' | '+String(settings.website).trim() : ''}`;
   const addressLine=String(settings.address||'').trim();
   // Show company details in the footer for both the default and gallery layouts.
   const wrappedFooterLines=useCustomLayout?[]:[companyName, phoneEmail, gstWebsite, addressLine].filter(line=>line.trim() && !/^(Phone|GSTIN)\s*(\|)?\s*$/.test(line));
   const footerLineH=3.8;
   const footerH=useCustomLayout?customFooterH:Math.max(25,wrappedFooterLines.length*footerLineH+7);
   const contentH=pageH-headerH-footerH-2;
   // Allow the document to grow naturally. One page is used for short orders;
   // additional A4 pages are added automatically when the order has more rows.
   // The company header and footer are repeated on every page.
   const pxPerMm=canvas.width/contentW;
   const maxContentPx=Math.floor(contentH*pxPerMm);
   const renderedContentPx=canvas.height;
   const pageCount=Math.max(1,Math.ceil(renderedContentPx/maxContentPx));
   const jpegQuality=0.94;
   for(let pageIndex=0; pageIndex<pageCount; pageIndex++){
     if(pageIndex>0) pdf.addPage();
     if(useCustomLayout){pdf.addImage(selectedLayoutImage,'JPEG',0,0,pageW,pageH,undefined,'FAST');}
     else pdf.addImage(PDF_HEADER,'JPEG',side,0,contentW,headerH,undefined,'FAST');

     const startY=pageIndex*maxContentPx;
     const sliceH=Math.min(maxContentPx,renderedContentPx-startY);
     const pageCanvas=document.createElement('canvas');
     pageCanvas.width=canvas.width;
     pageCanvas.height=sliceH;
     const ctx=pageCanvas.getContext('2d');
     if(!useCustomLayout){ctx.fillStyle='#fff';ctx.fillRect(0,0,pageCanvas.width,pageCanvas.height);}
     ctx.drawImage(canvas,0,startY,canvas.width,sliceH,0,0,canvas.width,sliceH);
     const sliceData=useCustomLayout?pageCanvas.toDataURL('image/png'):pageCanvas.toDataURL('image/jpeg',jpegQuality);
     const sliceMm=sliceH/pxPerMm;
     if(useCustomLayout)pdf.addImage(sliceData,'PNG',side,headerH,contentW,sliceMm,undefined,'FAST');
     else pdf.addImage(sliceData,'JPEG',side,headerH,contentW,sliceMm,undefined,'FAST');

     {
     // Default design keeps its colored footer band. For a complete gallery template,
     // preserve the uploaded footer artwork and place company details inside that area.
     if(!useCustomLayout){pdf.setFillColor(44,31,145);pdf.rect(0,pageH-footerH,pageW,footerH,'F');pdf.setTextColor(255,255,255);}
     else {pdf.setTextColor(0,0,0);}
     pdf.setFont('helvetica','bold');
     const footerStartY=pageH-footerH+(useCustomLayout?Math.min(5,footerH/5):4.5);
     const footerLineHActual=useCustomLayout?Math.min(3.6,(footerH-3)/Math.max(1,wrappedFooterLines.length)):footerLineH;
     wrappedFooterLines.forEach((line,i)=>{
       const y=footerStartY+i*footerLineHActual;
       let fontSize=useCustomLayout?6.8:7.2;
       const availableW=pageW-2*side;
       while(fontSize>4.2){pdf.setFontSize(fontSize);if(pdf.getTextWidth(line)<=availableW)break;fontSize-=0.2;}
       pdf.text(line,pageW/2,y,{align:'center'});
     });
     }
   }
   const no=$(type+"No").value||type.toUpperCase();
   const customerName=String($(type+"Customer").value||"").trim();
   const firstTwoNames=customerName.split(/\\s+/).filter(Boolean).slice(0,2).join(" ");
   const filePrefix=type==="invoice"?"INV":"QUO";
   const rawDate=String($(type+"Date").value||"").trim();
   const dateParts=rawDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
   const fileDate=dateParts?`${dateParts[3]}-${dateParts[2]}-${dateParts[1]}`:rawDate.replace(/[^0-9-]/g,"-");
   const pdfFileName=(filePrefix+"-"+(firstTwoNames||"Customer")+"-"+(fileDate||"Date")+".pdf").replace(/[\\/:*?"<>|]/g,"-");
   pdf.save(pdfFileName);
   const savedRecord={id:editingFileId||Date.now(),type,no,date:$(type+'Date').value,customer:$(type+'Customer').value,total:totals(type).total,status:(editingFileId?(files.find(f=>f.id===editingFileId)?.status||"pending"):"pending"),html:area.innerHTML,docData:{customer:$(type+'Customer').value,phone:$(type+'Phone').value,address:$(type+'Address').value,sales:$(type+'Sales').value,date:$(type+'Date').value,no:$(type+'No').value,lines:JSON.parse(JSON.stringify(lines[type]))}};
   if(editingFileId){
     const idx=files.findIndex(f=>f.id===editingFileId);
     if(idx>=0)files[idx]=savedRecord; else files.push(savedRecord);
   }else files.push(savedRecord);
   const wasEditing=!!editingFileId;
   editingFileId=null;
   const saveBtn=$(type+"SaveButton");if(saveBtn)saveBtn.textContent="Save PDF";
   try{await saveFilesDB(files);setPDFStatus(type,wasEditing?'Saved document updated successfully.':'PDF generated and saved successfully.',false);renderFiles('all');updateDashboard()}catch(storageErr){console.error('Saved-document history could not be stored:',storageErr);setPDFStatus(type,'PDF downloaded successfully. Its history could not be saved in browser storage; free up device storage and try again.',true)}
 }catch(err){console.error('PDF generation error:',err);setPDFStatus(type,'PDF could not be generated: '+(err?.message||String(err))+' — check internet connection and reload the website.',true);}
 finally{area.style.position=old.position;area.style.left=old.left||'-100000px';area.style.top=old.top;area.style.zIndex=old.zIndex;area.style.visibility=old.visibility||'hidden';area.style.display=old.display||'block';area.style.width=old.width||'794px'}
}
function normalizeFileStatus(file){file.status=(file.status==="approved"?"approved":"pending");return file;}
function statusBadge(status){
 return status==="approved"?'<span class="status-badge approved">Approved</span>':'<span class="status-badge pending">Pending</span>';
}
function approveFile(id){
 const f=files.find(x=>x.id===id);if(!f)return;
 if(f.status!=="pending")return;
 f.status="approved";
 saveFilesDB(files).then(()=>{renderFiles("all");updateDashboard();}).catch(()=>alert("Could not save approval status. Please try again."));
}
function renderFiles(filter){
 files.forEach(normalizeFileStatus);
 let arr=files.filter(f=>{
   if(filter==="pending"||filter==="approved")return f.status===filter;
   return filter==="all"||f.type===filter;
 }).slice().reverse();
 $("fileList").innerHTML=arr.length?arr.map(f=>`<div class="file-row"><div><b>${f.type==="invoice"?"Proforma Invoice":"Quotation"} ${esc(f.no)}</b><div class="file-status-line">${statusBadge(f.status)}</div></div><span>${esc(f.customer||"")}</span><span>${esc(f.date)}</span><b>₹${money(f.total)}</b><div class="file-actions"><button class="secondary" onclick="previewSavedFile(${f.id})">Preview</button><button class="secondary" onclick="editSavedFile(${f.id})">Edit Details</button>${f.status==="pending"?`<button class="approve-button" onclick="approveFile(${f.id})">Pending</button>`:`<button class="approved-button" disabled>Approved</button>`}<button class="primary" onclick="createNewFromSaved('${f.type}')">Create New</button><button class="danger" onclick="deleteFile(${f.id})">Delete</button></div></div>`).join(""):'<div class="empty">No saved records in this view. Saved PDFs are also downloaded to your computer.</div>';
}
function previewSavedFile(id){
 const f=files.find(x=>x.id===id);
 if(!f)return;
 if(!f.html){alert("Preview is not available for this older saved file.");return;}
 const overlay=document.createElement("div");
 overlay.className="preview-overlay";
 overlay.innerHTML=`<div class="preview-dialog"><div class="preview-toolbar"><b>${f.type==="invoice"?"Proforma Invoice":"Quotation"} Preview</b><button class="secondary" onclick="this.closest('.preview-overlay').remove()">Close</button></div><div class="preview-body">${f.html}</div></div>`;
 document.body.appendChild(overlay);
 overlay.addEventListener("click",e=>{if(e.target===overlay)overlay.remove()});
}
function editSavedFile(id){
 const f=files.find(x=>x.id===id);
 if(!f)return;
 if(!f.docData){alert("This older saved file does not contain editable details. New saved files will support editing.");return;}
 const type=f.type, d=f.docData;
 editingFileId=f.id;
 const saveBtn=$(type+"SaveButton");if(saveBtn)saveBtn.textContent="Update Saved PDF";
 $(type+"No").value=d.no||f.no||number(type);
 $(type+"Date").value=d.date||f.date||today();
 $(type+"Customer").value=d.customer||f.customer||"";
 $(type+"Phone").value=d.phone||"";
 $(type+"Address").value=d.address||"";
 $(type+"Sales").value=d.sales||"";
 lines[type]=JSON.parse(JSON.stringify(d.lines||[]));
 updateProducts(type);$(type+"Price").value="";renderLines(type);
 document.querySelectorAll(".nav").forEach(x=>x.classList.remove("active"));
 const nav=document.querySelector(`.nav[data-page="${type}"]`);if(nav)nav.classList.add("active");
 document.querySelectorAll(".page").forEach(x=>x.classList.remove("active"));
 $(type).classList.add("active");
 $("pageTitle").textContent=type==="invoice"?"Create Proforma Invoice":"Create Quotation";
}
function createNewFromSaved(type){setupDoc(type);document.querySelectorAll(".nav").forEach(x=>x.classList.remove("active"));const nav=document.querySelector(`.nav[data-page="${type}"]`);if(nav)nav.classList.add("active");document.querySelectorAll(".page").forEach(x=>x.classList.remove("active"));$(type).classList.add("active");$("pageTitle").textContent=type==="invoice"?"Create Proforma Invoice":"Create Quotation";}
async function deleteFile(id){
 if(confirm("Delete saved record?")){
   files=files.filter(f=>f.id!==id);
   if(editingFileId===id)editingFileId=null;
   await saveFilesDB(files);renderFiles("all");updateDashboard();
 }
}
function newDocument(type){setupDoc(type)}
function isValidPhone(value){
 const raw=String(value||"").trim();
 if(!raw)return true;
 // Accept Indian 10-digit mobile numbers, optionally prefixed by +91, 91, or 0.
 const digits=raw.replace(/[\s().-]/g,"");
 if(!/^\+?\d+$/.test(digits))return false;
 let national=digits;
 if(national.startsWith("+91"))national=national.slice(3);
 else if(national.startsWith("91")&&national.length===12)national=national.slice(2);
 else if(national.startsWith("0")&&national.length===11)national=national.slice(1);
 return /^[6-9]\d{9}$/.test(national);
}
function money(n){return Number(n||0).toLocaleString("en-IN",{minimumFractionDigits:2,maximumFractionDigits:2})}
function esc(v){return String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]))}
function nl(v){return esc(v).replace(/\n/g,"<br>")}

function goToPage(page){
 const btn=document.querySelector(`.nav[data-page="${page}"]`);
 if(btn)btn.click();
}
function openStatusFiles(filter){
 goToPage("files");
 renderFiles(filter);
}
function updateDashboard(){
 const normalized=files.map(normalizeFileStatus);
 const total=normalized.length;
 const pending=normalized.filter(f=>f.status==="pending").length;
 const approved=normalized.filter(f=>f.status==="approved").length;
 if($("statTotal"))$("statTotal").textContent=total;
 if($("statPending"))$("statPending").textContent=pending;
 if($("statApproved"))$("statApproved").textContent=approved;
 if($("statProducts"))$("statProducts").textContent=products.length;
 const recent=normalized.slice().sort((a,b)=>(Number(b.id)||0)-(Number(a.id)||0)).slice(0,5);
 if($("recentFiles"))$("recentFiles").innerHTML=recent.length?recent.map(f=>`<div class="recent-row"><div><b>${f.type==="invoice"?"Proforma Invoice":"Quotation"} ${esc(f.no)}</b><small>${esc(f.customer||"")} · ${esc(f.date||"")}</small></div><div>${statusBadge(f.status)}<strong>₹${money(f.total)}</strong></div></div>`).join(""):'<div class="empty">No invoices or quotations have been saved yet.</div>';
}


// Navigation wiring: required for every sidebar page to open.
document.querySelectorAll(".nav").forEach(btn=>btn.onclick=()=>{
 document.querySelectorAll(".nav").forEach(x=>x.classList.remove("active"));
 btn.classList.add("active");
 document.querySelectorAll(".page").forEach(x=>x.classList.remove("active"));
 const page=$(btn.dataset.page);
 if(page)page.classList.add("active");
 $("pageTitle").textContent=btn.textContent.trim();
 if(btn.dataset.page==="dashboard")updateDashboard();
 if(btn.dataset.page==="products")renderProducts();
 if(btn.dataset.page==="files")renderFiles("all");
 if(btn.dataset.page==="settings")loadSettings();
});
if($("invoiceSearch"))$("invoiceSearch").oninput=()=>updateProducts("invoice");
if($("quotationSearch"))$("quotationSearch").oninput=()=>updateProducts("quotation");

async function initializeApp(){
 setupDoc("invoice");
 setupDoc("quotation");
 loadSettings();
 try{
  let legacy=[];
  try{legacy=JSON.parse(localStorage.getItem(key.products)||"[]");if(!Array.isArray(legacy))legacy=[];}catch(_){legacy=[];}
  products=await loadProductsDB();
  files=await loadFilesDB();
  let statusChanged=false;
  files.forEach(f=>{if(f.status!=="approved"&&f.status!=="pending"){f.status="pending";statusChanged=true;}});
  if(!files.length&&legacyFiles.length){files=legacyFiles.map(normalizeFileStatus);await saveFilesDB(files);}
  if(!products.length&&legacy.length){products=legacy;await saveProductsDB(products);}
  if(statusChanged)await saveFilesDB(files);
 }catch(err){
  console.error("Storage initialization failed:",err);
  try{products=JSON.parse(localStorage.getItem(key.products)||"[]");}catch(_){products=[];}
  try{files=JSON.parse(localStorage.getItem(key.files)||"[]");}catch(_){files=[];}
 }
 renderProducts();
 updateProducts("invoice");
 updateProducts("quotation");
 renderFiles("all");
 updateDashboard();
}
initializeApp();
